//go:build mpv

// Integration tests against a real mpv binary. Run with:
//
//	go test -tags mpv ./internal/player/
//
// Audio is generated by lavfi (no network) and sent to --ao=null.
package player

import (
	"context"
	"os"
	"sync"
	"testing"
	"time"
)

const sine = "av://lavfi:sine=frequency=440:duration=600"

// recordingLauncher remembers the engines it started so the test can kill mpv.
type recordingLauncher struct {
	inner *MPVLauncher
	mu    sync.Mutex
	engs  []*mpvEngine
}

func (r *recordingLauncher) Launch(ctx context.Context, o LaunchOptions) (Engine, error) {
	e, err := r.inner.Launch(ctx, o)
	if err == nil {
		r.mu.Lock()
		r.engs = append(r.engs, e.(*mpvEngine))
		r.mu.Unlock()
	}
	return e, err
}

func (r *recordingLauncher) last() *mpvEngine {
	r.mu.Lock()
	defer r.mu.Unlock()
	return r.engs[len(r.engs)-1]
}

func until(t *testing.T, c *Controller, desc string, f func(State) bool) {
	t.Helper()
	deadline := time.Now().Add(10 * time.Second)
	for !f(c.State()) {
		if time.Now().After(deadline) {
			t.Fatalf("timeout: %s (state %+v)", desc, c.State())
		}
		time.Sleep(10 * time.Millisecond)
	}
}

// near allows for lavfi's approximate seeking (observed ~0.2 s short).
func near(got, want time.Duration) bool {
	return got > want-500*time.Millisecond && got < want+500*time.Millisecond
}

func TestRealMPV(t *testing.T) {
	dir, err := os.MkdirTemp("", "ytm")
	if err != nil {
		t.Fatal(err)
	}
	defer os.RemoveAll(dir)
	rl := &recordingLauncher{inner: &MPVLauncher{RuntimeDir: dir, ExtraArgs: []string{"--ao=null"}}}
	c := Start(context.Background(), Options{Launcher: rl, Volume: 60})
	defer func() {
		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		defer cancel()
		if err := c.Close(ctx); err != nil {
			t.Error(err)
		}
	}()
	go func() {
		for range c.Events() {
		}
	}()

	_ = c.Load(context.Background(), Item{ID: "sine", URL: sine}, 5*time.Second)
	until(t, c, "playing", func(s State) bool { return s.Status == Playing && s.Position >= 5*time.Second })
	// lavfi sources have no container duration; mpv reports a growing
	// estimate, so only check that one arrived.
	until(t, c, "duration", func(s State) bool { return s.Duration > 0 })

	_ = c.Pause()
	until(t, c, "paused", func(s State) bool { return s.Status == Paused })
	_ = c.Seek(90*time.Second, SeekAbsolute)
	until(t, c, "seeked", func(s State) bool {
		return near(s.Position, 90*time.Second)
	})
	_ = c.Seek(-30*time.Second, SeekRelative)
	until(t, c, "seeked back", func(s State) bool {
		return near(s.Position, 60*time.Second)
	})
	_ = c.SetVolume(25)
	until(t, c, "volume", func(s State) bool { return s.Volume == 25 })

	// kill -9 mpv: the controller must relaunch and resume, paused, at ~60 s.
	eng := rl.last()
	if err := eng.cmd.Process.Kill(); err != nil {
		t.Fatal(err)
	}
	until(t, c, "resumed", func(s State) bool {
		return rl.last() != eng && s.Status == Paused && s.Item.ID == "sine" &&
			near(s.Position, 60*time.Second) && s.Volume == 25
	})

	_ = c.Play()
	until(t, c, "playing after restore", func(s State) bool { return s.Status == Playing })
}
